style:
.vunapos-launcher {
  align-items: center;
  background: linear-gradient(135deg, var(--card-bg), var(--control-bg));
  border: 1px solid var(--border-color);
  border-radius: 12px;
  color: var(--text-color);
  display: flex;
  gap: 14px;
  min-height: 88px;
  padding: 16px;
  text-decoration: none;
  transition: border-color 120ms ease, box-shadow 120ms ease, transform 120ms ease;
}

.vunapos-launcher:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-sm);
  color: var(--text-color);
  text-decoration: none;
  transform: translateY(-1px);
}

.vunapos-launcher__logo {
  border-radius: 12px;
  height: 52px;
  object-fit: contain;
  width: 52px;
}

.vunapos-launcher__copy {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 3px;
}

.vunapos-launcher__copy strong {
  font-size: 15px;
}

.vunapos-launcher__copy small {
  color: var(--text-muted);
  font-size: 12px;
}

.vunapos-launcher__arrow {
  color: var(--primary);
  font-size: 22px;
}
